// LinkOffersByHash attaches a grab to the offer carrying the same infohash.
//
// UPDATE @@table g
//
//	 SET offer_id = o.id
//	FROM (SELECT DISTINCT ON (infohash) id, infohash
//	        FROM offers
//	       WHERE infohash IS NOT NULL
//	       ORDER BY infohash, (kind = 'announce') DESC, discovered_at) o
//
// WHERE g.offer_id IS NULL
//
//	AND g.torrent_infohash IS NOT NULL
//	AND o.infohash = g.torrent_infohash
func (g grabDo) LinkOffersByHash() (rowsAffected int64, err error) {
	var generateSQL strings.Builder
	generateSQL.WriteString("UPDATE grabs g SET offer_id = o.id FROM (SELECT DISTINCT ON (infohash) id, infohash FROM offers WHERE infohash IS NOT NULL ORDER BY infohash, (kind = 'announce') DESC, discovered_at) o WHERE g.offer_id IS NULL AND g.torrent_infohash IS NOT NULL AND o.infohash = g.torrent_infohash ")

	var executeSQL *gorm.DB
	executeSQL = g.UnderlyingDB().Exec(generateSQL.String()) // ignore_security_alert
	rowsAffected = executeSQL.RowsAffected
	err = executeSQL.Error

	return
}

// LinkOffersByRelease attaches a grab to an announce of the same release on the same indexer.
//
// UPDATE @@table g
//
//	 SET offer_id = o.id
//	FROM (SELECT DISTINCT ON (release_id, indexer_name) id, release_id, indexer_name
//	        FROM offers
//	       WHERE kind = 'announce' AND release_id IS NOT NULL
//	       ORDER BY release_id, indexer_name, discovered_at) o
//
// WHERE g.offer_id IS NULL
//
//	AND g.release_id IS NOT NULL
//	AND g.indexer_name IS NOT NULL
//	AND g.release_id = o.release_id
//	AND g.indexer_name = o.indexer_name
func (g grabDo) LinkOffersByRelease() (rowsAffected int64, err error) {
	var generateSQL strings.Builder
	generateSQL.WriteString("UPDATE grabs g SET offer_id = o.id FROM (SELECT DISTINCT ON (release_id, indexer_name) id, release_id, indexer_name FROM offers WHERE kind = 'announce' AND release_id IS NOT NULL ORDER BY release_id, indexer_name, discovered_at) o WHERE g.offer_id IS NULL AND g.release_id IS NOT NULL AND g.indexer_name IS NOT NULL AND g.release_id = o.release_id AND g.indexer_name = o.indexer_name ")

	var executeSQL *gorm.DB
	executeSQL = g.UnderlyingDB().Exec(generateSQL.String()) // ignore_security_alert
	rowsAffected = executeSQL.RowsAffected
	err = executeSQL.Error

	return
}

