func (g grabDo) FindInBatch(batchSize int, fc func(tx gen.Dao, batch int) error) (results []*model.Grab, err error) {
	buf := make([]*model.Grab, 0, batchSize)
	err = g.DO.FindInBatches(&buf, batchSize, func(tx gen.Dao, batch int) error {
		defer func() { results = append(results, buf...) }()
		return fc(tx, batch)
	})
	return results, err
}

